+const markerRegex = /^\\s*(?:<!--\\s*linter-(disable-next-n-lines|disable-next-line|disable|enable)(?::\\s*(\\S+))?(?:\\s+(.*?))?\\s*-->|%%\\s*linter-(disable-next-n-lines|disable-next-line|disable|enable)(?::\\s*(\\S+))?(?:\\s+(.*?))?\\s*%%)\\s*$/i;
+
+/**
+ * Applies a function while preserving marker lines and the lines disabled for a
+ * particular rule. Markers in YAML, code, or math are deliberately not parsed.
+ */
+export function applyWithScopedRuleIgnores(text: string, ruleAlias: string, knownAliases: Iterable<string>, apply: (text: string) => string): string {
+  const aliases = new Set(Array.from(knownAliases, (alias) => alias.toLowerCase()));
+  const lines = text.split('\
');
+  const ignoredMarkerLines = getIgnoredMarkerLines(text);
+  const protectedLines = new Set<number>();
+  const scopes: Scope[] = [];
+  const lineScopes: LineScope[] = [];
+
+  for (let lineNumber = 0; lineNumber < lines.length; lineNumber++) {
+    const marker = !ignoredMarkerLines.has(lineNumber) ? parseMarker(lines[lineNumber], aliases) : null;
+    if (marker) {
+      protectedLines.add(lineNumber);
+      applyMarker(marker, scopes, lineScopes, lineNumber, lines.length);
+      continue;
+    }
+
+    if (isDisabled(ruleAlias, scopes, lineScopes, lineNumber)) {
+      protectedLines.add(lineNumber);
+    }
+  }
+
+  if (protectedLines.size === 0) {
+    return apply(text);
+  }
+
+  const replacements: string[] = [];
+  for (const lineNumber of protectedLines) {
+    replacements.push(lines[lineNumber]);
+    lines[lineNumber] = `SCOPED_RULE_IGNORE_${replacements.length - 1}_PLACEHOLDER`;
+  }
+
+  let result = apply(lines.join('\
'));
+  replacements.forEach((line, index) => {
+    result = result.replace(new RegExp(`SCOPED_RULE_IGNORE_${index}_PLACEHOLDER`, 'i'), () => line);
+  });
+  return result;
+}
+
+type Marker = {kind: string, count: number, rules: Set<string>, all: boolean};
+
+function parseMarker(line: string, aliases: Set<string>): Marker | null {
+  const match = line.match(markerRegex);
+  if (!match) return null;
+
+  const kind = (match[1] ?? match[4]).toLowerCase();
+  const countText = match[2] ?? match[5];
+  const ruleText = match[3] ?? match[6] ?? '';
+  if (kind === 'disable-next-n-lines' && !/^[1-9]\\d*$/.test(countText ?? '')) return {kind: 'invalid', count: 0, rules: new Set(), all: false};
+
+  const rules = new Set(ruleText.split(',').map((rule) => rule.trim().toLowerCase()).filter((rule) => rule !== '' && aliases.has(rule)));
+  const all = ruleText.trim() === '' && kind !== 'enable';
+  return {kind, count: kind === 'disable-next-n-lines' ? Number(countText) : 1, rules, all};
+}
+
+function applyMarker(marker: Marker, scopes: Scope[], lineScopes: LineScope[], lineNumber: number, lineCount: number): void {
+  if (marker.kind === 'invalid') return;
+  if (marker.kind === 'disable' && (marker.all || marker.rules.size > 0)) {
+    scopes.push({all: marker.all, rules: marker.rules, enabledRules: new Set()});
+  } else if ((marker.kind === 'disable-next-line' || marker.kind === 'disable-next-n-lines') && lineNumber + 1 < lineCount && (marker.all || marker.rules.size > 0)) {
+    lineScopes.push({end: Math.min(lineCount - 1, lineNumber + marker.count), all: marker.all, rules: marker.rules});
+  } else if (marker.kind === 'enable') {
+    if (marker.rules.size === 0) {
+      scopes.pop();
+      return;
+    }
+    for (const rule of marker.rules) {
+      for (let index = scopes.length - 1; index >= 0; index--) {
+        const scope = scopes[index];
+        if (!scopeDisables(scope, rule)) continue;
+        if (scope.all) scope.enabledRules.add(rule);
+        else scope.rules.delete(rule);
+        if (!scope.all && scope.rules.size === 0) scopes.splice(index, 1);
+        break;
+      }
+    }
+  }
+}
+
+function isDisabled(ruleAlias: string, scopes: Scope[], lineScopes: LineScope[], lineNumber: number): boolean {
+  const alias = ruleAlias.toLowerCase();
+  return scopes.some((scope) => scopeDisables(scope, alias)) || lineScopes.some((scope) => lineNumber <= scope.end && (scope.all || scope.rules.has(alias)));
+}
+
+function scopeDisables(scope: Scope, rule: string): boolean {
+  return scope.all ? !scope.enabledRules.has(rule) : scope.rules.has(rule);
+}
+
+function getIgnoredMarkerLines(text: string): Set<number> {
+  const protectedRanges: {start: number, end: number}[] = [];
+  const yaml = text.match(yamlRegex);
+  if (yaml?.index === 0) protectedRanges.push({start: 0, end: yaml[0].length});
+  for (const type of [MDAstTypes.Code, MDAstTypes.Math, MDAstTypes.InlineCode, MDAstTypes.InlineMath]) {
+    for (const position of getPositions(type, text)) protectedRanges.push({start: position.start.offset, end: position.end.offset});
+  }
+
+  const result = new Set<number>();
+  let offset = 0;
+  for (const [lineNumber, line] of text.split('\
').entries()) {
+    const end = offset + line.length;
+    if (protectedRanges.some((range) => range.start <= end && range.end >= offset)) result.add(lineNumber);
+    offset = end + 1;
+  }
+  return result;
+}
